use clap::Parser;
use sotf_audio::LoudnessCompensation;
use sotf_audio::run_preflight_checks;
use std::fs::OpenOptions;

#[path = "sotf_player_cli/build.rs"]
mod build;
#[path = "sotf_player_cli/create.rs"]
mod create;
#[path = "sotf_player_cli/misc.rs"]
mod misc;
#[path = "sotf_player_cli/parse.rs"]
mod parse;
#[path = "sotf_player_cli/types.rs"]
mod types;
#[cfg(test)]
#[path = "sotf_player_cli/tests.rs"]
mod tests;

use build::play_stream;
use misc::list_devices;
use parse::parse_filters;
use parse::parse_loudness_compensation;
use types::Cli;
use types::Commands;

fn main() {
    let cli = Cli::parse();

    // Log to file when possible, but fall back to stderr if the current
    // directory is read-only (e.g. running from `/` or as a systemd unit).
    // Users can override the log path with the SOTF_CLI_LOG env var.
    let log_path =
        std::env::var("SOTF_CLI_LOG").unwrap_or_else(|_| "sotf_cli_player.log".to_string());
    let mut builder = env_logger::Builder::from_default_env();
    builder
        .filter_level(log::LevelFilter::Debug)
        .filter_module("symphonia_core", log::LevelFilter::Debug);
    match OpenOptions::new().create(true).append(true).open(&log_path) {
        Ok(log_file) => {
            builder.target(env_logger::Target::Pipe(Box::new(log_file)));
        }
        Err(e) => {
            eprintln!(
                "Warning: could not open log file {:?}: {}; falling back to stderr.",
                log_path, e
            );
            builder.target(env_logger::Target::Stderr);
        }
    }
    builder.init();

    log::info!("SOTF CLI Player starting...");

    // Run pre-flight checks before initializing the player
    if matches!(cli.command, Commands::Play { .. })
        && let Err(e) = run_preflight_checks()
    {
        eprintln!("\nPre-flight check failed:\n");
        eprintln!("{}\n", e);
        log::error!("Pre-flight check failed: {}", e);
        std::process::exit(1);
    }

    match cli.command {
        Commands::Devices => {
            if let Err(e) = list_devices() {
                log::error!("Error: {}", e);
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Commands::ReplayGain { file } => match sotf_audio::replaygain::analyze_file(&file) {
            Ok(info) => {
                let msg = format!(
                    "ReplayGain analysis:\n  File: {:?}\n  Gain: {:+.2} dB\n  Peak: {:.6}",
                    file, info.gain, info.peak
                );
                log::info!("{}", msg);
                println!("{}", msg);
            }
            Err(e) => {
                log::error!("Error: {}", e);
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        },
        Commands::Play {
            file,
            device,
            filters,
            hwaudio_play,
            duration,
            start_time,
            _buffer_chunks,
            lufs,
            loudness_compensation,
            loudness_auto_gain,
            loudness_auto_gain_max_db,
            loudness_auto_gain_smoothing_ms,
            rack,
            plugins,
        } => {
            if _buffer_chunks.is_some() {
                let msg = "Warning: --buffer-chunks is deprecated and currently has no effect.";
                log::warn!("{}", msg);
                eprintln!("{}", msg);
            }

            // Parse filters
            let filter_params = match parse_filters(&filters) {
                Ok(params) => params,
                Err(e) => {
                    log::error!("Error parsing filters: {}", e);
                    eprintln!("Error parsing filters: {}", e);
                    std::process::exit(1);
                }
            };

            // Parse loudness compensation
            let loudness: Option<LoudnessCompensation> = match loudness_compensation {
                Some(ref vals) => parse_loudness_compensation(vals).unwrap_or_else(|e| {
                    log::error!("Error in --loudness-compensation: {}", e);
                    eprintln!("Error in --loudness-compensation: {}", e);
                    std::process::exit(1);
                }),
                None => None,
            };

            if let Err(e) = play_stream(
                file,
                device,
                filter_params,
                duration,
                start_time,
                hwaudio_play,
                lufs,
                loudness,
                loudness_auto_gain,
                loudness_auto_gain_max_db,
                loudness_auto_gain_smoothing_ms,
                rack,
                &plugins,
            ) {
                log::error!("Error: {}", e);
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
        Commands::Status => {
            log::info!("Status command not yet implemented (requires running manager instance)");
        }
    }
}

